const SIDEBAR_ZONE = '[data-tree-group]:has([data-slot="sidebar"])'

// Dashed corner brackets around a box, drawn with gradients so no markup is needed.
const bracket = color => {
  const h = `linear-gradient(90deg, ${color} 0 3px, transparent 3px 5px, ${color} 5px 8px, transparent 8px 10px, ${color} 10px 12px)`
  const v = `linear-gradient(180deg, ${color} 0 3px, transparent 3px 5px, ${color} 5px 8px)`

  return {
    image: [h, h, h, h, v, v, v, v].join(','),
    size: '12px 1px, 12px 1px, 12px 1px, 12px 1px, 1px 8px, 1px 8px, 1px 8px, 1px 8px',
    position: 'left top, right top, left bottom, right bottom, left top, right top, left bottom, right bottom'
  }
}

const B = bracket('var(--skin-ink)')

// Custom properties for one mode: art, ink and wordmark colours.
function modeVars(V, ART, suffix) {
  return `
  --skin-ink: ${V.ink};
  --skin-dim: ${V.dim};
  --skin-rule: color-mix(in srgb, ${V.rule} 32%, transparent);
  --skin-dots: radial-gradient(circle at center, ${V.wordmarkDots} 0.55px, transparent 1px);
  --skin-wordmark: linear-gradient(180deg, ${V.wordmark.join(', ')});
  --skin-wordmark-shadow: ${V.wordmarkShadow};
  --skin-surface: ${V.surface};
  --skin-send: ${V.send};
  --skin-send-ink: ${V.sendInk};
  --skin-hero: url("${ART['hero' + suffix]}");
  --skin-top: url("${ART['top' + suffix]}");
  --skin-bottom: url("${ART['bottom' + suffix]}");`
}

function cssFor(THEME) {
  const ART = THEME.art
  const FX = new Set(THEME.fx || [])
  const hasLight = Boolean(THEME.lightVars && ART['hero-light'])
  // Prefix match: picking an accent colour renames the active theme to `<name>-accent-<hex>`.
  const T = `:root[data-hermes-theme^="${THEME.name}"]`
  const HERO = `${T} [data-slot="aui_intro"]`
  const THREAD = `${T} [data-slot="thread"]`

  return `
${T} {${modeVars(THEME.vars, ART, '')}
  --skin-art-floor: 250px;
}
${hasLight ? `${T}[data-hermes-mode="light"] {${modeVars(THEME.lightVars, ART, '-light')}
}` : ''}

${T} ${SIDEBAR_ZONE} > [data-panel-header] {
  position: relative;
  height: 262px !important;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
  content: '';
  position: absolute;
  inset: 0 0 18px 0;
  background: var(--skin-top) center 0 / 320px auto no-repeat;
  image-rendering: pixelated;
  -webkit-mask-image: linear-gradient(to bottom, #000 72%, transparent);
  mask-image: linear-gradient(to bottom, #000 72%, transparent);
  pointer-events: none;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-window-drag-handle] {
  z-index: 1;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-zone-tabstrip] {
  z-index: 1;
  background: transparent;
  padding-inline: 14px;
  gap: 10px;
}

${T} [data-tree-group]:not(:has([data-slot="sidebar"])) > [data-panel-header] > [data-zone-tabstrip] {
  padding-left: 10px;
}

${T} [data-slot="sidebar"] {
  position: relative;
  isolation: isolate;
  border-right: 1px dotted var(--skin-rule) !important;
}

${T} [data-slot="sidebar"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: auto 0 0 0;
  height: var(--skin-art-floor);
  background: var(--skin-bottom) center bottom / 320px auto no-repeat;
  image-rendering: pixelated;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 40%);
  mask-image: linear-gradient(to bottom, transparent, #000 40%);
  pointer-events: none;
}

/* the session list stops where the art starts fading in, and scrolls above it */
${T} [data-slot="sidebar"] [data-slot="sidebar-content"] > *:last-child {
  padding-bottom: var(--skin-art-floor);
}

${T} [data-slot="pane-tab"],
${T} [data-tree-tab] {
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 0 !important;
  box-shadow: none !important;
}

${T} [data-slot="pane-tab"][data-active="true"],
${T} [data-tree-tab][data-active="true"] {
  color: var(--skin-ink);
  background-color: transparent !important;
  background-image: ${B.image};
  background-size: ${B.size};
  background-position: ${B.position};
  background-repeat: no-repeat;
}

${T} [data-slot="pane-tab"][data-active="true"]::after,
${T} [data-tree-tab][data-active="true"]::after {
  display: none !important;
}

${T} [data-slot="pane-tab"][data-active="false"] {
  color: var(--skin-dim);
}

${T} [data-tree-group][data-window-top] > [data-panel-header] {
  border-bottom: 1px dotted var(--skin-rule);
}

${T} [data-sash-overlap] {
  opacity: 0;
}

${T} [data-slot="composer-surface"] {
  border: 1px dashed color-mix(in srgb, var(--skin-ink) 55%, transparent) !important;
  border-radius: 6px !important;
  background: var(--skin-surface) !important;
  box-shadow: none !important;
}

${T} [data-slot="kbd"] {
  font-family: var(--font-mono);
  background: transparent !important;
  border: 1px dashed color-mix(in srgb, var(--skin-ink) 60%, transparent) !important;
  color: var(--skin-ink) !important;
}

${T} [data-slot="sidebar-input"],
${T} [data-slot="sidebar"] input[type="search"] {
  border: 0 !important;
  border-bottom: 1px dotted var(--skin-rule) !important;
  border-radius: 0 !important;
  background: transparent !important;
}

/* chat pane: the hero art, huge and faint, behind every conversation */
${THREAD} {
  position: relative;
  isolation: isolate;
}

${THREAD}:not(:has([data-slot="aui_intro"]))::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  background: var(--skin-hero) center 30% / auto 80% no-repeat;
  image-rendering: pixelated;
  opacity: 0.1;
  -webkit-mask-image: radial-gradient(ellipse 60% 55% at 50% 35%, #000 40%, transparent);
  mask-image: radial-gradient(ellipse 60% 55% at 50% 35%, #000 40%, transparent);
  pointer-events: none;
}
${FX.has('stars') ? `
/* a slowly drifting, twinkling star field over the top of the pane (dark mode) */
${THREAD}::after {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0 0 35% 0;
  background: url("${THEME.stars}") 0 0 / 384px 384px repeat;
  image-rendering: pixelated;
  -webkit-mask-image: linear-gradient(to bottom, #000 30%, transparent);
  mask-image: linear-gradient(to bottom, #000 30%, transparent);
  animation: skin-drift 240s linear infinite, skin-twinkle 3.6s steps(3) infinite alternate;
  pointer-events: none;
}
${hasLight ? `${T}[data-hermes-mode="light"] [data-slot="thread"]::after { display: none; }` : ''}
` : ''}

/* empty chat: the hero art above the wordmark, as wide as the pane allows */
${HERO} {
  position: relative;
  isolation: isolate;
  overflow: visible;
}

${HERO}::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: calc(100% - 175px);
  width: min(1280px, calc(100vw - 380px));
  aspect-ratio: 8 / 3;
  max-height: 50vh;
  transform: translateX(-50%);
  background: var(--skin-hero) center bottom / contain no-repeat;
  image-rendering: pixelated;
  pointer-events: none;${FX.has('float') ? `
  animation: skin-float 7s steps(4) infinite alternate;` : ''}${FX.has('pulse') ? `
  animation: skin-pulse 2.6s ease-in-out infinite alternate;` : ''}
}

${FX.has('shine') ? `
/* a light sweep across the hero, masked to the art itself */
${HERO}::after {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: calc(100% - 175px);
  width: min(1280px, calc(100vw - 380px));
  aspect-ratio: 8 / 3;
  max-height: 50vh;
  transform: translateX(-50%);
  background: linear-gradient(105deg, transparent 42%, rgba(255, 255, 255, 0.5) 50%, transparent 58%) 0 0 / 300% 100% no-repeat;
  -webkit-mask: var(--skin-hero) center bottom / contain no-repeat;
  mask: var(--skin-hero) center bottom / contain no-repeat;
  mix-blend-mode: soft-light;
  animation: skin-shine 8s ease-in-out infinite;
  pointer-events: none;
}` : `
/* blueprint rules either side of the wordmark */
${HERO}::after {
  content: '';
  position: absolute;
  z-index: -1;
  left: 4%;
  right: 4%;
  top: 40px;
  height: 120px;
  background:
    linear-gradient(90deg, var(--skin-rule) 50%, transparent 50%) left 0 / 6px 1px repeat-x,
    linear-gradient(90deg, var(--skin-rule) 50%, transparent 50%) left 100% / 6px 1px repeat-x;
  pointer-events: none;
}`}

@keyframes skin-drift { to { background-position: 384px 768px; } }
@keyframes skin-twinkle { from { opacity: 0.45; } to { opacity: 1; } }
@keyframes skin-float { from { transform: translate(-50%, 0); } to { transform: translate(-50%, -8px); } }
@keyframes skin-pulse { from { filter: brightness(1); } to { filter: brightness(1.14) saturate(1.1); } }
@keyframes skin-shine { 0%, 55% { background-position: 100% 0; } 85%, 100% { background-position: 0% 0; } }

@media (prefers-reduced-motion: reduce) {
  ${HERO}::before, ${HERO}::after, ${THREAD}::after { animation: none !important; }
}

${T} .wordmark {
  mix-blend-mode: normal !important;
}

${T} .wordmark > span:not([aria-hidden]) > span {
  color: transparent;
  background:
    var(--skin-dots) 0 0 / 3px 3px,
    var(--skin-wordmark);
  -webkit-background-clip: text;
  background-clip: text;
  /* a tight edge plus a soft halo of the background, so the title reads over busy art */
  filter: drop-shadow(0 0 1px var(--skin-wordmark-shadow)) drop-shadow(0 0 4px var(--skin-wordmark-shadow));
}

${T} [data-slot="aui_intro"] p:not(.wordmark) {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  line-height: 1.7;
  color: var(--skin-ink);
  max-width: 44ch;
  margin-inline: auto;
}

${T} [data-slot="composer-surface"] button[data-variant="default"] {
  background: var(--skin-send) !important;
  color: var(--skin-send-ink) !important;
}
`
}

const desktopTheme = THEME => ({
  name: THEME.name,
  label: THEME.label,
  description: THEME.description,
  // `colors` is the light palette and `darkColors` the dark one; a theme without a
  // light edition keeps its dark palette in both, so its art never lands on a light ground.
  colors: THEME.lightColors || THEME.colors,
  darkColors: THEME.colors,
  typography: THEME.typography,
  terminal: THEME.lightTerminal || THEME.terminal,
  darkTerminal: THEME.terminal,
  customCSS: cssFor(THEME)
})

export default {
  id: 'hermes-desktop-skins',
  name: 'Hermes Desktop Skins',
  register(ctx) {
    ctx.registerMany(THEMES.map(THEME => ({ id: THEME.name, area: THEMES_AREA, data: desktopTheme(THEME) })))
  }
}
